import com.twintrade.app.MarketStore;import org.json.*;
public class MarketStoreTest{
 static void check(boolean b,String why){if(!b)throw new AssertionError(why);}static long due(String s){check(s.startsWith("PENDING:"),s);return Long.parseLong(s.substring(8));}
 public static void main(String[] args)throws Exception{MarketStore.init(new android.content.Context());MarketStore.seed("{\"cash\":100,\"positions\":[],\"history\":[]}");long now=System.currentTimeMillis();MarketStore.tick(0,100,now-1000);String zero="{\"fee\":0,\"slip\":0,\"borrow\":0,\"funding\":0,\"liq\":90}";long openDue=due(MarketStore.open(0,true,10,10,zero));JSONObject b=new JSONObject(MarketStore.book());check(b.getDouble("cash")==90,"pending open did not reserve $10");check(b.getJSONArray("positions").length()==0,"pending open filled early");MarketStore.advancePendingForTests(0,105,openDue);b=new JSONObject(MarketStore.book());check(b.getJSONArray("positions").getJSONObject(0).getDouble("amount")==10,"delayed open amount incorrect");check(b.getJSONArray("positions").getJSONObject(0).getDouble("entry")==105,"open did not use execution-time price");MarketStore.tick(0,80,System.currentTimeMillis());b=new JSONObject(MarketStore.book());check(b.getJSONArray("positions").length()==1,"liquidation filled without delay");long liqDue=b.getJSONArray("pending").getJSONObject(0).getLong("due");MarketStore.advancePendingForTests(0,79,liqDue);b=new JSONObject(MarketStore.book());check(b.getJSONArray("positions").length()==0,"delayed liquidation did not settle");check(b.getJSONArray("history").getJSONObject(0).getString("status").equals("Liquidated"),"liquidation not recorded");check(b.getJSONArray("history").getJSONObject(0).getDouble("exit")==79,"liquidation did not use execution-time price");check(MarketStore.lastLiquidationSide()==1,"background liquidation side unavailable");MarketStore.reset();MarketStore.tick(0,100,System.currentTimeMillis());openDue=due(MarketStore.open(0,false,100,10,zero));MarketStore.advancePendingForTests(0,100,openDue);check(new JSONObject(MarketStore.book()).getDouble("cash")==0,"100 percent leaves cash");MarketStore.merge(0,new JSONArray("[{\"t\":"+(now-120000)+",\"o\":100,\"h\":100,\"l\":90,\"c\":90}]"));MarketStore.tick(0,90,System.currentTimeMillis());JSONObject snap=new JSONObject(MarketStore.snapshot());check(snap.getJSONArray("candles").getJSONArray(0).length()>=2,"background minute candles missing");String id=new JSONObject(MarketStore.book()).getJSONArray("positions").getJSONObject(0).getString("id");long closeDue=due(MarketStore.close(id));MarketStore.advancePendingForTests(0,90,closeDue);check(new JSONObject(MarketStore.book()).getDouble("cash")>100,"short profit missing");MarketStore.reset();check(new JSONObject(MarketStore.book()).getJSONArray("history").length()==0,"respawn did not clear history");System.out.println("PASS: native delayed sizing, collateral reservation, execution-time fills, liquidation, settlement and candles.");}
}
